mapper.select:
SELECT COALESCE (sit.taskNum,0) as taskNum, mc.market_tenant, mc.market_name FROM market_config mc LEFT JOIN ( select market_tenant,market_name,count(id) as taskNum from safety_inspect_record
and market_tenant = #{query.marketTenant}
and `time` >= #{query.period.begin} and `time` < #{query.period.end}
and task_id is null
and `result` = #{query.result}
group by market_tenant order by taskNum desc ) sit ON mc.market_tenant = sit.market_tenant
mc.status = true
and sit.market_tenant in
#{marketTenant}

select sir.id ,sir.`time` ,sir.target_name ,sir.market_tenant ,sir.market_name ,sir.user_id ,sir.nickname ,sir.`result`
     ,sir.task_id,sir.task_name,GROUP_CONCAT(siri.id) as record_item_id, GROUP_CONCAT(siri.item_name) as errorItem,
      count(siri.id) as errNumber
from safety_inspect_record sir
left join safety_inspect_record_item siri on(siri.record_id = sir.id and siri.error_value_flag = 1)


        and sir.`time` >= #{query.period.begin} and `time` < #{query.period.end}


        and sir.target_id = #{query.targetId}


        and task_id is null


        and sir.market_tenant = #{query.marketTenant}


        and sir.`result` = #{query.result}


        and sir.target_name = #{query.targetName}


        and siri.item_tag is not null


        and siri.item_tag in

            #{tag}



group by sir.id order by sir.`time` desc

select sir.id ,sir.`time` ,sir.target_name ,sir.market_tenant ,sir.market_name ,sir.user_id ,sir.nickname ,sir.`result`
,sir.task_id,sir.task_name,GROUP_CONCAT(siri.id) as record_item_id, GROUP_CONCAT(siri.item_name) as errorItem,GROUP_CONCAT(siri.item_tag) as errorTag,
count(siri.id) as errNumber
from safety_inspect_record sir
inner join safety_inspect_record_item siri on(siri.record_id = sir.id and siri.error_value_flag = 1)


        and sir.`time` >= #{query.period.begin} and `time` < #{query.period.end}


        and sir.target_id = #{query.targetId}


        and task_id is null


        and sir.market_tenant = #{query.marketTenant}


        and sir.`result` = #{query.result}


        and sir.target_name = #{query.targetName}


        and siri.item_tag is not null


        and siri.item_tag in

            #{tag}



group by sir.id order by sir.`time` desc
